<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\UserInvitation\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\TemporalKeysGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\TemporalAuthCode;
use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\OAuth\UserInvitation\Domain\Gateway\UserInvitationCodeGateway;

class UserInvitationCodeAdapter implements UserInvitationCodeGateway
{
    public function __construct(
        private readonly LoginGateway $loginGateway,
        private readonly ClientStoreGateway $clientStore,
        private readonly TemporalKeysGateway $temporalKeys,
    ) {
    }

    #[Override]
    public function createAuthCode(
        string $userUid,
        string $clientId,
        string $scope,
        string $redirectUri,
        string $tenant,
    ): string {
        $client = $this->clientStore->preValidatedClient($clientId);
        if ($client === null) {
            throw new \DomainException('Client not found: ' . $clientId);
        }

        $authRequest = new AuthenticationRequest(
            client: $client,
            scope: $scope,
            redirect: $redirectUri,
            responseType: 'code',
            audiences: [$clientId],
        );

        $challenges  = (new ChallengesState())->withUsername($userUid);
        $authResult  = $this->loginGateway->fillPreLoadById($tenant, $authRequest, $challenges);

        $temporalCode = new TemporalAuthCode(
            data: $authResult,
            client: $client,
            nonce: '',
            request: $authRequest,
        );

        return $this->temporalKeys->registerTemporalAuthCode($temporalCode);
    }
}
